async function testPostAgain() {
    console.log('\n=== Final Verification Test ===');

    try {
        const fs = require('fs');
        const envContent = fs.readFileSync('.env.test', 'utf8');

        const postResult = await new Promise((resolve) => {
            const options = {
                hostname: 'localhost',
                port: 47301,
                path: '/api/verify',
                method: 'POST',
                headers: {
                    'Content-Type': 'text/plain',
                    'Content-Length': Buffer.byteLength(envContent)
                }
            };

            const req = http.request(options, (res) => {
                let data = '';
                res.on('data', (chunk) => data += chunk);
                res.on('end', () => resolve({ statusCode: res.statusCode, body: data }));
            });

            req.on('error', (error) => resolve({ error: error.message }));
            req.write(envContent);
            req.end();
        });

        if (postResult.body) {
            console.log('POST /api/verify result:', postResult.body);
        }
    } catch (e) {
        console.log('Verification test error:', e.message);
    }
}

